def calc_b_coeffs_new(x1, y1, x2, y2, z1, z2, sens):
    u0 = 4 * np.pi * 1e-7
    a = np.array([x1, y1, z1])
    b = np.array([x2, y2, z2])
    u = b - a
    v = sens - a

    cross = np.cross(u, v)

    b_1 = np.dot(v,u)/np.linalg.norm(v)
    b_2 = (np.linalg.norm(u)**2-np.dot(v,u))/np.linalg.norm(sens-b)

    return (u0/(4*np.pi))*(cross/(np.linalg.norm(cross))**2)*(b_1+b_2)


def calc_curr_segments(leiter_seg_arr, b_vec, sens_pos):

    A = None

    for pos in sens_pos:

        cols = []
        for segs in leiter_seg_arr:
            b_ges = 0
            for l in segs:
                b_ges += calc_b_coeffs_new(*l,pos)

            cols.append(b_ges)

        if A is None:
            A = np.array(cols).T
        else:
            A = np.vstack([A, np.array(cols).T])

    b = np.array(b_vec).flatten()

    x, residuals, rank, s = np.linalg.lstsq(A, b, rcond=None)

    return x*1000


def calc_curr_segments_xyz(leiter_seg_arr, b_vec, sens_pos_x, sens_pos_y, sens_pos_z):

    A = None

    for i in range(len(sens_pos_x)):

        cols = []
        for segs in leiter_seg_arr:
            b_ges_x = 0
            b_ges_y = 0
            b_ges_z = 0
            for l in segs:
                b_ges_x += calc_b_coeffs_new(*l,sens_pos_x[i])
                b_ges_y += calc_b_coeffs_new(*l, sens_pos_y[i])
                b_ges_z += calc_b_coeffs_new(*l, sens_pos_z[i])

            cols.append(np.array([b_ges_x[0], b_ges_y[1], b_ges_z[2]]))

        if A is None:
            A = np.array(cols).T
        else:
            A = np.vstack([A, np.array(cols).T])

    b = np.array(b_vec).flatten()

    x, residuals, rank, s = np.linalg.lstsq(A, b, rcond=None)

    return x*1000

